<?php
namespace App\Core\Agents\Tools\FirstParty;use App\Core\Agents\Contracts\RiskLevel;use App\Core\Agents\Tools\Contracts\AgentTool;use App\Core\Agents\Tools\DTO\ToolExecutionResult;use App\Models\{AgentRun,Lead,LeadActivity};
final class LeadActivityTool implements AgentTool {public function name():string{return 'leads.add_activity';}public function description():string{return 'Record a research, note, outreach draft, meeting or status activity on an Enverif lead.';}public function risk():RiskLevel{return RiskLevel::InternalWrite;}public function parameters():array{return ['type'=>'object','properties'=>['lead_id'=>['type'=>'integer'],'type'=>['type'=>'string'],'summary'=>['type'=>'string'],'data'=>['type'=>'object']],'required'=>['lead_id','type','summary']];}public function execute(AgentRun $run,array $a):ToolExecutionResult{$lead=Lead::where('workspace_id',$run->workspace_id)->findOrFail((int)$a['lead_id']);$activity=LeadActivity::create(['workspace_id'=>$run->workspace_id,'lead_id'=>$lead->id,'run_id'=>$run->id,'type'=>(string)$a['type'],'summary'=>(string)$a['summary'],'data'=>$a['data']??null]);return ToolExecutionResult::success(['activity_id'=>$activity->id,'lead_id'=>$lead->id]);}}
